var n=`1190-arroz-con-leche`;var a=`world-1190`;var r=`MX`;var t=`central-america-caribbean`;var o=8;var s=118;var c={en:`Arroz con Leche`,ua:`Рисовий пудинг аррос кон лече`};var l={en:`Arroz con Leche is a dish from Mexico prepared with white rice, whole cow milk, evaporated milk, raisin. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Рисовий пудинг аррос кон лече, страва кухні країни Мексика, яку готують із таких продуктів: білий рис, цільне коров'яче молоко, концентроване молоко без цукру, родзинки. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 33 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 33 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:33,i:[[`white-rice`,320,`g`],[`whole-cow-milk`,900,`ml`],[`water`,350,`ml`],[`ceylon-cinnamon`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`white-granulated-sugar`,145,`g`],[`evaporated-milk`,240,`ml`],[`vanilla-extract`,5,`ml`]]},{en:`Refrigerate the prepared mixture for about 75 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 75 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:75,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-cinnamon`,4,`g`],[`raisin`,80,`g`]]}];var m={slug:n,id:a,country:`MX`,region:t,servings:8,minutes:118,title:c,text:l,steps:d};export{r as country,m as default,a as id,s as minutes,t as region,o as servings,n as slug,d as steps,l as text,c as title};